NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'I Thessalonians'

CHAPTERS = {
    1: {
        1: 'Paavali, Silas ja Timoteus tessalonikalaisten seurakunnalle Isässä Jumalassa ja Herrassa Jeesuksessa Kristuksessa. Armo teille ja rauha!',
        2: 'Kiitämme Jumalaa aina kaikkien teidän tähtenne mainiten teitä rukouksissamme lakkaamatta',
        3: 'ja muistaen työtänne uskossa ja vaivannäköänne rakkaudessa ja kärsivällisyyttänne toivossa Herraamme Jeesukseen Kristukseen Jumalamme ja Isämme edessä.',
        4: 'Tiedämme, Jumalan rakastamat veljet, teidän valitsemisenne:',
        5: 'että evankeliumimme tuli luoksenne, ei ainoastaan sanana, vaan myös voimana ja Pyhässä Hengessä ja suurella varmuudella – niin kuin tiedätte, millaisia olimme teidän keskuudessanne, teidän tähtenne –',
        6: 'ja teistä tuli meidän seuraajiamme ja Herran, kun suuressa ahdingossa otitte sanan vastaan Pyhän Hengen vaikuttamalla ilolla,',
        7: 'niin että teistä on tullut esikuvia kaikille uskoville Makedoniassa ja Akaiassa.',
        8: 'Sillä teidän toimestanne Herran sana on kaikunut, ei ainoastaan Makedoniaan ja Akaiaan, vaan kaikkialle uskonne Jumalaan on levinnyt, niin ettei meidän tarvitse puhua siitä mitään.',
        9: 'Sillä itse he kertovat meistä, millainen tulomme oli luoksenne ja kuinka te epäjumalista käännyitte Jumalan luo palvelemaan elävää ja oikeaa Jumalaa',
        10: 'ja odottamaan taivaista hänen Poikaansa, jonka hän herätti kuolleista, Jeesusta, joka pelastaa meidät tulevasta vihasta.',
    },
    2: {
        1: 'Tiedättehän itsekin, veljet, ettei tulomme teidän luoksenne ollut turha,',
        2: 'vaan, vaikka olimme ennen kärsineet, kuten tiedätte, Filipissä ja meitä oli siellä pidelty pahoin, meillä oli kuitenkin Jumalassamme rohkeutta puhua teille Jumalan evankeliumia suuressa kilvoituksessa.',
        3: 'Sillä meidän kehotuspuheemme ei lähde eksytyksestä eikä epäpuhtaasta mielestä eikä ole kavaluudessa puhuttua,',
        4: 'vaan niin kuin Jumala on katsonut meidät kelvollisiksi siihen, että meille uskottiin evankeliumi, puhumme, emme ollaksemme ihmisille mieliksi, vaan Jumalalle, joka koettelee sydämemme.',
        5: 'Sillä emme esiintyneet koskaan mielistelevin puhein, kuten tiedätte, emmekä tekosyillä ahnehtineet. Jumala on todistajamme.',
        6: 'Emme ole etsineet kunniaa ihmisiltä, emme teiltä emmekä muilta,',
        7: 'vaikka Kristuksen apostoleina olisimme voineet saada teiltä arvonantoa. Olimme sen sijaan keskuudessanne lempeitä kuin imettävä äiti, joka vaalii lapsiaan.',
        8: 'Niin mekin teitä hellien halusimme antaa teille, emme ainoastaan Jumalan evankeliumia, vaan oman henkemmekin, sillä olitte meille rakkaita.',
        9: 'Muistattehan, veljet, meidän työmme ja rasituksemme: yötä päivää työtä tehden saarnasimme teille Jumalan evankeliumia, niin ettemme ketään teistä rasittaisi.',
        10: 'Te olette todistajamme, ja Jumala, kuinka pyhät, vanhurskaat ja nuhteettomat olimme teitä kohtaan, jotka uskotte,',
        11: 'samoin kuin tiedätte, kuinka me, niin kuin isä lapsiaan, kehotimme itse kutakin teistä ja rohkaisimme teitä,',
        12: 'ja todistimme teille, että teidän tulee vaeltaa arvollisesti Jumalan edessä, hänen, joka kutsuu teitä valtakuntaansa ja kirkkauteensa.',
        13: 'Sen tähden me myös kiitämme lakkaamatta Jumalaa siitä, että saatuanne saarnaamamme Jumalan sanan otitte sen vastaan, ette ihmisten sanana, vaan, niin kuin se totisesti on, Jumalan sanana, joka myös vaikuttaa teissä, jotka uskotte.',
        14: 'Sillä teistä, veljet, on tullut niiden Kristuksessa Jeesuksessa olevien Jumalan seurakuntien seuraajia, jotka ovat Juudeassa, sillä tekin olette kärsineet omilta heimolaisiltanne samaa kuin he juutalaisilta,',
        15: 'jotka tappoivat Herrankin, Jeesuksen, ja omia profeettojaan ja ovat vainonneet meitä, eivätkä ole Jumalalle otollisia, vaan ovat kaikkien ihmisten vihollisia,',
        16: 'kun estävät meitä puhumasta pakanoille heidän pelastumisekseen täyttääkseen kaiken aikaa syntiensä mittaa. Viha onkin jo saavuttanut heidät viimeiseen määräänsä asti.',
        17: 'Mutta kun meidät nyt, veljet, on hetkeksi aikaa erotettu teistä, kasvoilta, ei sydämeltä, on meille tullut yhä suurempi halu nähdä pian kasvonne.',
        18: 'Sen tähden olemme tahtoneet tulla luoksenne, minä, Paavali puolestani kerran ja kahdestikin, mutta saatana on estänyt meitä.',
        19: 'Sillä kuka on toivomme, ilomme tai kerskauksemme kruunu? Ettekö tekin, Herramme Jeesuksen edessä hänen tulemuksessaan?',
        20: 'Sillä te olette kunniamme ja ilomme.',
    },
    3: {
        1: 'Sen tähden, kun emme enää kestäneet, katsoimme parhaaksi jäädä yksin Ateenaan,',
        2: 'ja lähetimme Timoteuksen, veljemme ja Jumalan palvelijan Kristuksen evankeliumissa, vahvistamaan ja rohkaisemaan teitä uskossanne,',
        3: 'ettei kukaan horjuisi näissä ahdingoissa. Sillä itse tiedätte, että meidät on sellaisiin pantu.',
        4: 'Kun olimme luonanne, sanoimme teille jo edeltäpäin, että joudumme ahdistuksiin, kuten myös tiedätte tapahtuneen.',
        5: 'Sen tähden minäkin, kun en enää kestänyt kauempaa, lähetin tiedustelemaan teidän uskoanne, olisiko ehkä kiusaaja vietellyt teidät ja olisiko vaivannäkömme mennyt hukkaan.',
        6: 'Mutta nyt, kun Timoteus tuli luoksemme luotanne ja kertoi meille hyviä uutisia uskostanne ja rakkaudestanne ja siitä, että aina säilytätte meistä hyvän muiston ikävöiden nähdä meitä niin kuin mekin teitä:',
        7: 'sen tähden olemme saaneet lohdutusta teistä, veljet, kaikkeen ahdistukseemme ja ahdinkoomme.',
        8: 'Nyt näet elämme, jos te seisotte lujina Herrassa.',
        9: 'Sillä miten voimme kylliksi osoittaa kiitollisuutta Jumalaa kohtaan teidän tähtenne kaikesta siitä ilosta, mikä meillä on teistä Jumalamme edessä!',
        10: 'Yötä päivää rukoilemme erittäin paljon saadaksemme nähdä kasvonne ja täyttää sen, mitä uskostanne puuttuu.',
        11: 'Mutta hän itse, Jumalamme ja Isämme, ja Herramme Jeesus ohjatkoon tiemme luoksenne.',
        12: 'Herra antakoon teille yhä enemmän ja runsaammin rakkautta toisianne kohtaan ja kaikkia kohtaan, niin kuin meilläkin on teitä kohtaan,',
        13: 'vahvistaakseen sydämenne nuhteettomiksi pyhyydessä Jumalamme ja Isämme edessä, Herramme Jeesuksen tullessa kaikkien pyhiensä kanssa.',
    },
    4: {
        1: 'Sitten vielä, veljet, pyydämme ja kehotamme teitä Herrassa Jeesuksessa, että kuten olette meiltä oppineet, miten teidän tulee vaeltaa ja olla Jumalalle otollisia, niin kuin vaellattekin, kasvaisitte siinä yhä enemmän.',
        2: 'Tiedättehän, mitkä käskyt olemme Herran Jeesuksen kautta teille antaneet.',
        3: 'Sillä tämä on Jumalan tahto, teidän pyhityksenne, että pysytte erossa haureudesta,',
        4: 'että kukin teistä tietää ottaa itselleen vaimon pyhyydessä ja kunniassa,',
        5: 'ei himon kiihkossa kuin pakanat, jotka eivät Jumalaa tunne,',
        6: 'ettei kukaan sorra veljeään eikä tuota hänelle vahinkoa missään asiassa. Herra on näet kaiken tämän kostaja, niin kuin myös ennen olemme teille sanoneet ja todistaneet.',
        7: 'Sillä Jumala ei ole kutsunut meitä saastaisuuteen, vaan pyhitykseen.',
        8: 'Sen tähden, joka nämä hylkää, ei hylkää ihmistä, vaan Jumalan, joka myös antaa Pyhän Henkensä teihin.',
        9: 'Veljesrakkaudesta teille ei tarvitse kirjoittaa, sillä Jumala on itse opettanut teidät rakastamaan toisianne.',
        10: 'Sillä niin teettekin kaikkia veljiä kohtaan koko Makedoniassa. Mutta kehotamme teitä, veljet, kasvamaan siinä yhä enemmän',
        11: 'ja katsomaan kunniaksenne, että elätte hiljaisuudessa ja toimitatte omia tehtäviänne ja teette työtä käsillänne, niin kuin olemme teitä käskeneet,',
        12: 'että vaelluksessanne olisitte säädyllisiä ulkopuolella olevia kohtaan ettekä olisi kenenkään avun tarpeessa.',
        13: 'Mutta en tahdo pitää teitä, veljet, tietämättöminä siitä, kuinka poisnukkuneiden on, ettette murehtisi niin kuin muut, joilla ei ole toivoa.',
        14: 'Sillä jos uskomme, että Jeesus on kuollut ja noussut ylös, niin samoin on Jumalakin Jeesuksen kautta tuova poisnukkuneet esiin yhdessä hänen kanssaan.',
        15: 'Sillä sen sanomme teille Herran sanana, että me, jotka olemme elossa, jotka jäämme tänne Herran tulemukseen, emme suinkaan ehdi ennen niitä, jotka ovat nukkuneet.',
        16: 'Sillä itse Herra on tuleva alas taivaasta käskyhuudon, ylienkelin äänen ja Jumalan torven kuuluessa. Kristuksessa kuolleet nousevat ylös ensin,',
        17: 'sitten meidät, jotka olemme elossa, jotka olemme jääneet tänne, temmataan yhdessä heidän kanssaan pilvissä Herraa vastaan ilmaan, ja niin saamme aina olla Herran kanssa.',
        18: 'Näin lohduttakaa toisianne näillä sanoilla.',
    },
    5: {
        1: 'Mutta aikakausista ja määrähetkistä ei ole tarpeen kirjoittaa teille, veljet,',
        2: 'sillä hyvin tiedätte, että Herran päivä tulee kuin varas yöllä.',
        3: 'Kun he sanovat: "Nyt on rauha ja turvallista", silloin heille tulee yhtäkkiä turmio kuin poltot raskaana olevalle vaimolle, eivätkä he pääse pakoon.',
        4: 'Mutta te, veljet, ette ole pimeydessä, niin että se päivä veisi teidät kuin varas.',
        5: 'Te kaikki olette nimittäin valkeuden lapsia ja päivän lapsia. Emme ole yön emmekä pimeyden lapsia.',
        6: 'Älkäämme siis nukkuko kuten muut, vaan valvokaamme ja olkaamme raittiit.',
        7: 'Sillä ne, jotka nukkuvat, yöllä nukkuvat, ja jotka juopuvat, ovat yöllä juovuksissa.',
        8: 'Mutta me, jotka olemme päivän lapsia, olkaamme raittiita, ja olkoon pukunamme uskon ja rakkauden haarniska ja kypäränämme pelastuksen toivo.',
        9: 'Sillä Jumala ei ole määrännyt meitä vihaan, vaan saamaan omaksemme pelastuksen Herramme Jeesuksen Kristuksen kautta,',
        10: 'joka on kuollut meidän edestämme, että olimmepa hereillä tai nukuimme, eläisimme yhdessä hänen kanssaan.',
        11: 'Sen tähden kehottakaa toisianne ja rakentakaa toinen toistanne, kuten teettekin.',
        12: 'Mutta pyydämme teitä, veljet, antamaan tunnustusta niille, jotka tekevät työtä teidän keskuudessanne ja ovat johtajianne Herrassa ja neuvovat teitä',
        13: 'sekä pitämään heitä erityisen rakkaina heidän työnsä tähden. Eläkää rauhassa heidän kanssaan.',
        14: 'Kehotamme teitä, veljet: nuhdelkaa kurittomia, rohkaiskaa alakuloisia, holhotkaa heikkoja, olkaa pitkämielisiä kaikkia kohtaan.',
        15: 'Katsokaa, ettei kukaan kosta kenellekään pahaa pahalla, vaan pyrkikää aina tekemään hyvää toinen toisellenne ja kaikille.',
        16: 'Olkaa aina iloiset.',
        17: 'Rukoilkaa lakkaamatta.',
        18: 'Kiittäkää joka tilassa. Sillä se on Jumalan tahto teihin nähden Kristuksessa Jeesuksessa.',
        19: 'Henkeä älkää sammuttako,',
        20: 'profetoimista älkää halveksiko,',
        21: 'mutta koetelkaa kaikki, pitäkää hyvä ja',
        22: 'karttakaa kaikkea pahalta näyttävää.',
        23: 'Mutta itse rauhan Jumala pyhittäköön teidät kokonaan, ja säilyköön koko teidän henkenne, sielunne ja ruumiinne nuhteettomana meidän Herramme Jeesuksen Kristuksen tuloon.',
        24: 'Hän, joka teitä kutsuu, on uskollinen, ja hän on myös sen tekevä.',
        25: 'Veljet, rukoilkaa edestämme.',
        26: 'Tervehtikää kaikkia veljiä pyhällä suudelmalla.',
        27: 'Minä vannotan teitä Herran kautta, että luetatte tämän kirjeen kaikille veljille.',
        28: 'Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne. Aamen.',
    },
}
